<script lang="ts">
import SvgIcon from "$lib/components/ui/Icon.svelte";
import Card from "$lib/components/ui/Card.svelte";
import CardContent from "$lib/components/ui/CardContent.svelte";
import Button from "$lib/components/ui/Button.svelte";
import Input from "$lib/components/ui/Input.svelte";
import CardHeader from "$lib/components/ui/CardHeader.svelte";
import CardTitle from "$lib/components/ui/CardTitle.svelte";

import {untrack} from "svelte";
import {page as routePage,navigating} from "$app/state";
import {goto,invalidateAll} from "$app/navigation";
import {notify} from "$lib/client/toast";
type Requisition = { id: string; requisitionNumber: string; title: string; status: string; openings: number; jobDescription: string };
type Job = { id: string; jobNumber: string; publicTitle: string; slug: string; status: string; applicationDeadline?: string | null };
type Candidate = { id: string; candidateNumber: string; fullName: string; email: string; currentDesignation?: string | null; location?: string | null; status: string };
type Employee = { id: string; displayName: string; employeeId: string };
type Application = { application: { id: string; status: string; currentStageId: string }; candidateName: string; jobTitle: string; stageName: string };
type Interview = { interview: { id: string; status: string; scheduledAt: string; interviewType: string; mode: string }; candidateName: string; jobTitle: string };
type Stage = { id: string; name: string };
async function read<T>(url: string): Promise<T> { const response = await fetch(url); const body = await response.json(); if (!response.ok || !body.success) throw new Error(body.error?.message ?? "Unable to load recruitment data."); return body; }
let requisitions=$state<Requisition[]>(untrack(()=>([])));
const setRequisitions=(next:typeof requisitions|((previous:typeof requisitions)=>typeof requisitions))=>{requisitions=typeof next==="function"?(next as (previous:typeof requisitions)=>typeof requisitions)(requisitions):next;};
let jobs=$state<Job[]>(untrack(()=>([])));
const setJobs=(next:typeof jobs|((previous:typeof jobs)=>typeof jobs))=>{jobs=typeof next==="function"?(next as (previous:typeof jobs)=>typeof jobs)(jobs):next;};
let candidates=$state<Candidate[]>(untrack(()=>([])));
const setCandidates=(next:typeof candidates|((previous:typeof candidates)=>typeof candidates))=>{candidates=typeof next==="function"?(next as (previous:typeof candidates)=>typeof candidates)(candidates):next;};
let applications=$state<Application[]>(untrack(()=>([])));
const setApplications=(next:typeof applications|((previous:typeof applications)=>typeof applications))=>{applications=typeof next==="function"?(next as (previous:typeof applications)=>typeof applications)(applications):next;};
let interviews=$state<Interview[]>(untrack(()=>([])));
const setInterviews=(next:typeof interviews|((previous:typeof interviews)=>typeof interviews))=>{interviews=typeof next==="function"?(next as (previous:typeof interviews)=>typeof interviews)(interviews):next;};
let employees=$state<Employee[]>(untrack(()=>([])));
const setEmployees=(next:typeof employees|((previous:typeof employees)=>typeof employees))=>{employees=typeof next==="function"?(next as (previous:typeof employees)=>typeof employees)(employees):next;};
let stages=$state<Stage[]>(untrack(()=>([])));
const setStages=(next:typeof stages|((previous:typeof stages)=>typeof stages))=>{stages=typeof next==="function"?(next as (previous:typeof stages)=>typeof stages)(stages):next;};
let query=$state(untrack(()=>("")));
const setQuery=(next:typeof query|((previous:typeof query)=>typeof query))=>{query=typeof next==="function"?(next as (previous:typeof query)=>typeof query)(query):next;};
let loading=$state(untrack(()=>(true)));
const setLoading=(next:typeof loading|((previous:typeof loading)=>typeof loading))=>{loading=typeof next==="function"?(next as (previous:typeof loading)=>typeof loading)(loading):next;};
let error=$state(untrack(()=>("")));
const setError=(next:typeof error|((previous:typeof error)=>typeof error))=>{error=typeof next==="function"?(next as (previous:typeof error)=>typeof error)(error):next;};
let message=$state(untrack(()=>("")));
const setMessage=(next:typeof message|((previous:typeof message)=>typeof message))=>{message=typeof next==="function"?(next as (previous:typeof message)=>typeof message)(message):next;};
let busy=$state(untrack(()=>(false)));
const setBusy=(next:typeof busy|((previous:typeof busy)=>typeof busy))=>{busy=typeof next==="function"?(next as (previous:typeof busy)=>typeof busy)(busy):next;};
let showRequisition=$state(untrack(()=>(false)));
const setShowRequisition=(next:typeof showRequisition|((previous:typeof showRequisition)=>typeof showRequisition))=>{showRequisition=typeof next==="function"?(next as (previous:typeof showRequisition)=>typeof showRequisition)(showRequisition):next;};
let showCandidate=$state(untrack(()=>(false)));
const setShowCandidate=(next:typeof showCandidate|((previous:typeof showCandidate)=>typeof showCandidate))=>{showCandidate=typeof next==="function"?(next as (previous:typeof showCandidate)=>typeof showCandidate)(showCandidate):next;};
let showJob=$state(untrack(()=>(false)));
const setShowJob=(next:typeof showJob|((previous:typeof showJob)=>typeof showJob))=>{showJob=typeof next==="function"?(next as (previous:typeof showJob)=>typeof showJob)(showJob):next;};
let requisitionForm=$state(untrack(()=>({ title: "", hiringManagerEmployeeId: "", openings: "1", jobDescription: "", workMode: "onsite" })));
const setRequisitionForm=(next:typeof requisitionForm|((previous:typeof requisitionForm)=>typeof requisitionForm))=>{requisitionForm=typeof next==="function"?(next as (previous:typeof requisitionForm)=>typeof requisitionForm)(requisitionForm):next;};
let candidateForm=$state(untrack(()=>({ firstName: "", lastName: "", email: "", phone: "", location: "", currentDesignation: "", consentStatus: "granted" })));
const setCandidateForm=(next:typeof candidateForm|((previous:typeof candidateForm)=>typeof candidateForm))=>{candidateForm=typeof next==="function"?(next as (previous:typeof candidateForm)=>typeof candidateForm)(candidateForm):next;};
let jobForm=$state(untrack(()=>({ requisitionId: "", publicTitle: "", publicDescription: "", slug: "", applicationDeadline: "", location: "", workMode: "" })));
const setJobForm=(next:typeof jobForm|((previous:typeof jobForm)=>typeof jobForm))=>{jobForm=typeof next==="function"?(next as (previous:typeof jobForm)=>typeof jobForm)(jobForm):next;};
const load=$derived.by(()=>{query;return async () => { setLoading(true); setError(""); try { const [req, job, candidate, application, interview, employee, pipeline] = await Promise.all([read<{ requisitions: Requisition[] }>("/api/app/ats/requisitions"), read<{ jobs: Job[] }>("/api/app/ats/jobs"), read<{ candidates: Candidate[] }>(`/api/app/ats/candidates?limit=100&q=${encodeURIComponent(query)}`), read<{ applications: Application[] }>("/api/app/ats/applications"), read<{ interviews: Interview[] }>("/api/app/ats/interviews/list"), read<{ employees: Employee[] }>("/api/app/ats/employee-options"), read<{ stages: Stage[] }>("/api/app/ats/pipeline")]); setRequisitions(req.requisitions); setJobs(job.jobs); setCandidates(candidate.candidates); setApplications(application.applications); setInterviews(interview.interviews); setEmployees(employee.employees); setStages(pipeline.stages); } catch (cause) { setError(cause instanceof Error ? cause.message : "Unable to load recruitment workspace."); } finally { setLoading(false); } };});
$effect(()=>{load;return untrack(() => { void load(); });});
const run = async (url: string, options: RequestInit) => { setBusy(true); setError(""); setMessage(""); try { const response = await fetch(url, options); const body = await response.json(); if (!response.ok || !body.success) throw new Error(body.error?.message ?? "The recruitment action could not be completed."); setMessage("Recruitment update completed."); await load(); return body; } catch (cause) { setError(cause instanceof Error ? cause.message : "The recruitment action could not be completed."); return null; } finally { setBusy(false); } };
const createRequisition = async (event: SubmitEvent) => { event.preventDefault(); await run("/api/app/ats/requisitions", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ...requisitionForm, openings: Number(requisitionForm.openings) }) }); setShowRequisition(false); };
const createCandidate = async (event: SubmitEvent) => { event.preventDefault(); await run("/api/app/ats/candidates", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(candidateForm) }); setShowCandidate(false); };
const createJob = async (event: SubmitEvent) => { event.preventDefault(); await run("/api/app/ats/jobs", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(jobForm) }); setShowJob(false); };
const visibleCandidates=$derived.by(() => candidates.filter((candidate) => !query || `${candidate.fullName} ${candidate.email} ${candidate.currentDesignation ?? ""}`.toLowerCase().includes(query.toLowerCase())));
const pending=$derived(requisitions.filter((item) => item.status === "pending_approval").length);
const activeJobs=$derived(jobs.filter((item) => ["published", "open"].includes(item.status)).length);
</script>
<div class="space-y-6">{#if error}<p role="alert" class="rounded-lg border border-danger/30 bg-danger/5 p-3 text-sm text-danger">{error}</p>{/if}{#if message}<p aria-live="polite" class="rounded-lg border border-success/30 bg-success/5 p-3 text-sm text-success">{message}</p>{/if}<div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-6">{#each [["Open requisitions", requisitions.filter((item) => ["approved", "open"].includes(item.status)) .length], ["Pending approvals", pending], ["Active jobs", activeJobs], ["Applications", applications.length], ["Interviews", interviews.length], ["Candidates", candidates.length]] as [label, value]}<Card><CardContent class="p-4"><p class="text-xs text-muted">{label}</p><p class="mt-2 text-2xl font-bold">{#if loading}{"…"}{:else}{value}{/if}</p></CardContent></Card>{/each}</div><div class="flex flex-wrap items-center gap-2"><Button onclick={() => setShowRequisition(!showRequisition)}>New requisition</Button><Button variant="secondary" onclick={() => setShowJob(!showJob)}>Create job</Button><Button variant="secondary" onclick={() => setShowCandidate(!showCandidate)}>Add candidate</Button><Input class="ml-auto max-w-sm" aria-label="Search candidates" placeholder="Search candidates" value={query} oninput={(event) => setQuery(event.currentTarget.value)} /></div>{#if showRequisition}<Card><CardHeader><CardTitle>Create requisition</CardTitle></CardHeader><CardContent><form onsubmit={createRequisition} class="grid gap-3 md:grid-cols-2"><Input required placeholder="Role title" value={requisitionForm.title} onchange={(event) => setRequisitionForm({ ...requisitionForm, title: event.currentTarget.value })} /><select required aria-label="Hiring manager" class="h-10 rounded-lg border bg-surface px-3" value={requisitionForm.hiringManagerEmployeeId} onchange={(event) => setRequisitionForm({ ...requisitionForm, hiringManagerEmployeeId: event.currentTarget.value })}><option value="">Hiring manager</option>{#each employees as employee}<option value={employee.id}>{employee.displayName} ({employee.employeeId})</option>{/each}</select><Input required min="1" type="number" placeholder="Openings" value={requisitionForm.openings} onchange={(event) => setRequisitionForm({ ...requisitionForm, openings: event.currentTarget.value })} /><select aria-label="Work mode" class="h-10 rounded-lg border bg-surface px-3" value={requisitionForm.workMode} onchange={(event) => setRequisitionForm({ ...requisitionForm, workMode: event.currentTarget.value })}><option value="onsite">On-site</option><option value="hybrid">Hybrid</option><option value="remote">Remote</option></select><textarea required minLength={10} class="min-h-28 rounded-lg border bg-surface p-3 md:col-span-2" placeholder="Job description" value={requisitionForm.jobDescription} onchange={(event) => setRequisitionForm({ ...requisitionForm, jobDescription: event.currentTarget.value })}></textarea><Button type="submit" disabled={busy}>Save draft</Button></form></CardContent></Card>{/if}{#if showJob}<Card><CardHeader><CardTitle>Create public job from approved requisition</CardTitle></CardHeader><CardContent><form onsubmit={createJob} class="grid gap-3 md:grid-cols-2"><select required aria-label="Approved requisition" class="h-10 rounded-lg border bg-surface px-3" value={jobForm.requisitionId} onchange={(event) => setJobForm({ ...jobForm, requisitionId: event.currentTarget.value })}><option value="">Select approved requisition</option>{#each requisitions.filter((item) => ["approved", "open"].includes(item.status)) as item}<option value={item.id}>{item.requisitionNumber} · {item.title}</option>{/each}</select><Input required placeholder="Public title" value={jobForm.publicTitle} onchange={(event) => setJobForm({ ...jobForm, publicTitle: event.currentTarget.value })} /><Input placeholder="Public slug" value={jobForm.slug} onchange={(event) => setJobForm({ ...jobForm, slug: event.currentTarget.value })} /><Input type="date" aria-label="Application deadline" value={jobForm.applicationDeadline} onchange={(event) => setJobForm({ ...jobForm, applicationDeadline: event.currentTarget.value })} /><textarea required minLength={10} class="min-h-28 rounded-lg border bg-surface p-3 md:col-span-2" placeholder="Public description" value={jobForm.publicDescription} onchange={(event) => setJobForm({ ...jobForm, publicDescription: event.currentTarget.value })}></textarea><Button type="submit" disabled={busy}>Create draft job</Button></form></CardContent></Card>{/if}{#if showCandidate}<Card><CardHeader><CardTitle>Add candidate</CardTitle></CardHeader><CardContent><form onsubmit={createCandidate} class="grid gap-3 md:grid-cols-2"><Input required placeholder="First name" value={candidateForm.firstName} onchange={(event) => setCandidateForm({ ...candidateForm, firstName: event.currentTarget.value })} /><Input required placeholder="Last name" value={candidateForm.lastName} onchange={(event) => setCandidateForm({ ...candidateForm, lastName: event.currentTarget.value })} /><Input required type="email" placeholder="Email" value={candidateForm.email} onchange={(event) => setCandidateForm({ ...candidateForm, email: event.currentTarget.value })} /><Input placeholder="Phone" value={candidateForm.phone} onchange={(event) => setCandidateForm({ ...candidateForm, phone: event.currentTarget.value })} /><Input placeholder="Location" value={candidateForm.location} onchange={(event) => setCandidateForm({ ...candidateForm, location: event.currentTarget.value })} /><Input placeholder="Current designation" value={candidateForm.currentDesignation} onchange={(event) => setCandidateForm({ ...candidateForm, currentDesignation: event.currentTarget.value })} /><Button type="submit" disabled={busy}>Save candidate</Button></form></CardContent></Card>{/if}<div class="grid gap-5 lg:grid-cols-2"><Card><CardHeader><CardTitle>Requisitions</CardTitle></CardHeader><CardContent class="space-y-3">{#if loading}<p class="text-sm text-muted">Loading requisitions…</p>{:else}{#if requisitions.length === 0}<p class="text-sm text-muted">No requisitions yet. Create the first draft to begin the approval workflow.</p>{:else}{#each requisitions as item}<div class="rounded-xl border p-4"><div class="flex flex-wrap justify-between gap-2"><div><p class="font-semibold">{item.title}</p><p class="text-xs text-muted">{item.requisitionNumber} · {item.openings} opening(s)</p></div><span class="rounded-full bg-surface px-3 py-1 text-xs capitalize">{item.status.replaceAll("_", " ")}</span></div>{#if item.status === "draft"}<Button class="mt-3" size="sm" variant="secondary" disabled={busy} onclick={() => run(`/api/app/ats/requisitions/${item.id}/submit`, { method: "POST" })}>Submit for approval</Button>{/if}</div>{/each}{/if}{/if}</CardContent></Card><Card><CardHeader><CardTitle>Jobs</CardTitle></CardHeader><CardContent class="space-y-3">{#if loading}<p class="text-sm text-muted">Loading jobs…</p>{:else}{#if jobs.length === 0}<p class="text-sm text-muted">No jobs created yet. Jobs can only be created from approved requisitions.</p>{:else}{#each jobs as job}<div class="rounded-xl border p-4"><div class="flex flex-wrap justify-between gap-2"><div><p class="font-semibold">{job.publicTitle}</p><p class="text-xs text-muted">{job.jobNumber} · /jobs/{job.slug}</p></div><span class="rounded-full bg-surface px-3 py-1 text-xs capitalize">{job.status}</span></div>{#if job.status === "draft"}<div class="mt-3 flex flex-wrap gap-2"><Button size="sm" disabled={busy} onclick={() => run(`/api/app/ats/jobs/${job.id}/publish`, { method: "POST" })}>Publish</Button><a class="text-sm font-semibold text-primary" href={`/jobs/${job.slug}`}>Preview public page</a></div>{/if}{#if job.status === "published"}<a class="mt-3 inline-block text-sm font-semibold text-primary" href={`/jobs/${job.slug}`}>Open public job</a>{/if}</div>{/each}{/if}{/if}</CardContent></Card><Card><CardHeader><CardTitle>Candidates</CardTitle></CardHeader><CardContent class="space-y-3">{#if loading}<p class="text-sm text-muted">Loading candidates…</p>{:else}{#if visibleCandidates.length === 0}<p class="text-sm text-muted">No candidates match the current search.</p>{:else}{#each visibleCandidates.slice(0, 20) as candidate}<a href={`/app/recruitment/candidates/${candidate.id}`} class="block rounded-xl border p-4 hover:bg-surface"><div class="flex justify-between gap-2"><div><p class="font-semibold">{candidate.fullName}</p><p class="text-xs text-muted">{candidate.candidateNumber} · {candidate.email}</p></div><span class="text-xs capitalize text-muted">{candidate.status}</span></div><p class="mt-1 text-sm text-muted">{candidate.currentDesignation ?? "Role not specified"} · {candidate.location ?? "Location not specified"}</p></a>{/each}{/if}{/if}</CardContent></Card><Card><CardHeader><CardTitle>Applications and interviews</CardTitle></CardHeader><CardContent class="space-y-3">{#if applications.length === 0 && interviews.length === 0}<p class="text-sm text-muted">No application or interview activity yet.</p>{:else}{#each applications.slice(0, 8) as item}<div class="rounded-xl border p-3 text-sm"><p class="font-medium">{item.candidateName} · {item.jobTitle}</p><p class="text-muted">Stage: {item.stageName} · {item.application.status}</p><select aria-label={`Move ${item.candidateName}`} class="mt-2 h-9 rounded-lg border bg-surface px-2" value={item.application.currentStageId} onchange={(event) => void run(`/api/app/ats/applications/${item.application.id}/stage`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ stageId: event.currentTarget.value }) })}><option value={item.application.currentStageId}>{item.stageName}</option>{#each stages.filter((stage) => stage.id !== item.application.currentStageId) as stage}<option value={stage.id}>{stage.name}</option>{/each}</select></div>{/each}{#each interviews.slice(0, 8) as item}<div class="rounded-xl border p-3 text-sm"><p class="font-medium">{item.candidateName} · {item.jobTitle}</p><p class="text-muted">{new Date(item.interview.scheduledAt).toLocaleString()} · {item.interview.mode} · {item.interview.status}</p></div>{/each}{/if}</CardContent></Card></div></div>
